@participant31 I found a solution: set the root view opacity to 0 initially and only show it after the app has finished initializing
```tsx
import { useEffect, useState } from "react";
import { View, Text, StyleSheet } from "react-native";
import * as SplashScreen from "expo-splash-screen";

SplashScreen.preventAutoHideAsync();

export const App = () => {
  const [isReady, setIsReady] = useState(false);

  useEffect(() => {
    const prepare = async () => {
      try {
        await new Promise(resolve => setTimeout(resolve, 1500));
      } catch (e) {
        console.warn(e);
      } finally {
        setIsReady(true);
        SplashScreen.hide();
      }
    }

    prepare();
  }, []);

  return (
    <View style={[styles.container, { opacity: isReady ? 1 : 0 }]}>
      <Text>Hello World</Text>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: "center",
    alignItems: "center",
  },
});
```

I checked how the solution works on this version
```json
"expo": "~55.0.0",
"expo-splash-screen": "~55.0.10"
```
